// PORTAO 3 (D3) - "Nunca confie no cliente": rota de ESCRITA so aceita pedido que veio da PROPRIA tela e em JSON.
// CORS sozinho NAO protege (o browser envia o POST mesmo assim); por isso o servidor confere Origin/Referer e Content-Type.
// Origem permitida = mesmo host da pagina (cabecalho Host) ou item de BT2_ORIGENS_OK (variavel da ABA, ex.: http://servidor:1880,null).
const h = (msg.req && msg.req.headers) || {};
const host = String(h.host || '').toLowerCase();
const extras = String(env.get('BT2_ORIGENS_OK') || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const hostDe = u => { try { return new URL(String(u)).host.toLowerCase(); } catch (e) { return null; } };
const origemDe = u => { try { return new URL(String(u)).origin.toLowerCase(); } catch (e) { return null; } };
let motivo = null;
if (h.origin !== undefined) {
  const o = String(h.origin).toLowerCase();
  if (!((host && hostDe(o) === host) || extras.includes(o))) motivo = 'origem_nao_permitida';
} else if (h.referer !== undefined) {
  const r = origemDe(h.referer);
  if (!((host && hostDe(h.referer) === host) || (r && extras.includes(r)))) motivo = 'origem_nao_permitida';
} else {
  motivo = 'sem_origem';
}
if (!motivo && !/^application\/json\s*(;|$)/i.test(String(h['content-type'] || ''))) motivo = 'content_type_invalido';
if (motivo) {
  node.warn('D3 bloqueado: ' + motivo + ' | ' + String((msg.req && msg.req.method) || '') + ' ' + String((msg.req && msg.req.url) || '').slice(0, 80) + ' | origin=' + String(h.origin || h.referer || '-').slice(0, 80));
  msg.statusCode = 403;
  msg.payload = { ok: false, codigo: 'D3_' + motivo, erro: 'pedido recusado: so e aceito da propria tela do medidor, em JSON (' + motivo + ')' };
  return [null, msg];
}
return [msg, null];

// C2: o medidor informa o kW a 100 % do gerador em ensaio. Guardado em global 'bt2_kw100_cliente' (vale por gerador.validade_s; o medidor reenvia a cada minuto).
const PADRAO = {"versao": "0.2", "data": "19/11/2026", "descricao": "Espelho versionado da capacidade dos bancos de carga e do limite de carga do gerador. A VERDADE do kW de cada chave e o setup.nominal[] no PLC do banco (DB3000/3100/3200/3300); este arquivo e o espelho que o Node-RED usa e que os testes conferem contra o medidor. Passo 5: C1 (registrar) e C2 (recusar, so quando modo = recusar).", "modo": "registrar", "modo_nota": "registrar = so anota no log (C1). recusar = o Node-RED recusa com HTTP 409 o comando de LIGAR chave que passaria do limite (C2). Padrao: registrar. So mudar para recusar depois de validar na bancada com carga desacoplada e com OK do Reginaldo. Desligar NUNCA e recusado.", "pctLim": 110, "pctLim_nota": "Limite de seguranca = kw100 x pctLim / 100. 110 % e o padrao provisorio unico (igual a G.pctLim do medidor), valido ate haver parametrizacao por modelo de gerador (ISO 3046-1: 110 % por 1 h).", "gerador": {"kw100": null, "kw100_nota": "kW a 100 % do gerador em ensaio. Se preenchido aqui, VALE ESTE (campanha com gerador fixo). null = o Node-RED usa o valor que o medidor informa em POST /api/gerador/capacidade (se recente); sem nenhum dos dois o limite NAO e avaliado (nunca recusa).", "kw100_max": 1000, "kw100_max_nota": "Teto aceito para o valor informado pelo medidor (protege contra valor absurdo). Acima disso a rota responde 400.", "validade_s": 180, "validade_s_nota": "Tempo em que o valor informado pelo medidor continua valendo sem novo aviso (o medidor reenvia a cada minuto). Vencido = limite NAO avaliado."}, "degrau": {"max_kw": null, "max_kw_nota": "Teto de carga NOVA (kW) que pode ser ligada dentro de janela_s segundos (soma das chaves ligadas na janela). null = degrau nao avaliado. Valor a confirmar pela Engenharia (BK-AUD-10): nao ha valor normativo adotado.", "janela_s": 10}, "bancos": {"56": {"id_medidor": "56", "db": 3000, "chaves_kw": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 4, 3]}, "400": {"id_medidor": "400", "db": 3100, "chaves_kw": [5, 5, 10, 10, 10, 10, 50, 50, 50, 50, 50, 50, 50]}, "595": {"id_medidor": "59,5", "db": 3200, "chaves_kw": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 3, 3, 2, 1, 0.5, 0.5, 0.5]}, "550": {"id_medidor": "550", "db": 3300, "chaves_kw": [5, 5, 5, 5, 5, 25, 50, 50, 100, 100, 100, 100]}}};
const cfg = global.get('bt2_capacidade') || PADRAO;
const max = Number(cfg.gerador && cfg.gerador.kw100_max) || 1000;
const b = msg.payload || {};
const kw = Number(b.kw100);
msg.headers = { 'Content-Type': 'application/json' };
if (!(typeof b.kw100 === 'number' || (typeof b.kw100 === 'string' && b.kw100.trim() !== '')) || !isFinite(kw) || !(kw > 0) || kw > max) {
  msg.statusCode = 400; msg.payload = { ok: false, codigo: 'KW100_INVALIDO', erro: 'kw100 deve ser um numero maior que 0 e ate ' + max + ' kW' };
  return msg;
}
const modelo = String(b.modelo || '').slice(0, 80);
global.set('bt2_kw100_cliente', { kw100: kw, modelo, ts: Date.now() });
msg.statusCode = 200; msg.payload = { ok: true, kw100: kw, modelo, validadeS: Number(cfg.gerador && cfg.gerador.validade_s) || 180 };
return msg;

// C2: mostra qual kW a 100 % o Node-RED esta usando para o limite e de onde veio.
const PADRAO = {"versao": "0.2", "data": "19/11/2026", "descricao": "Espelho versionado da capacidade dos bancos de carga e do limite de carga do gerador. A VERDADE do kW de cada chave e o setup.nominal[] no PLC do banco (DB3000/3100/3200/3300); este arquivo e o espelho que o Node-RED usa e que os testes conferem contra o medidor. Passo 5: C1 (registrar) e C2 (recusar, so quando modo = recusar).", "modo": "registrar", "modo_nota": "registrar = so anota no log (C1). recusar = o Node-RED recusa com HTTP 409 o comando de LIGAR chave que passaria do limite (C2). Padrao: registrar. So mudar para recusar depois de validar na bancada com carga desacoplada e com OK do Reginaldo. Desligar NUNCA e recusado.", "pctLim": 110, "pctLim_nota": "Limite de seguranca = kw100 x pctLim / 100. 110 % e o padrao provisorio unico (igual a G.pctLim do medidor), valido ate haver parametrizacao por modelo de gerador (ISO 3046-1: 110 % por 1 h).", "gerador": {"kw100": null, "kw100_nota": "kW a 100 % do gerador em ensaio. Se preenchido aqui, VALE ESTE (campanha com gerador fixo). null = o Node-RED usa o valor que o medidor informa em POST /api/gerador/capacidade (se recente); sem nenhum dos dois o limite NAO e avaliado (nunca recusa).", "kw100_max": 1000, "kw100_max_nota": "Teto aceito para o valor informado pelo medidor (protege contra valor absurdo). Acima disso a rota responde 400.", "validade_s": 180, "validade_s_nota": "Tempo em que o valor informado pelo medidor continua valendo sem novo aviso (o medidor reenvia a cada minuto). Vencido = limite NAO avaliado."}, "degrau": {"max_kw": null, "max_kw_nota": "Teto de carga NOVA (kW) que pode ser ligada dentro de janela_s segundos (soma das chaves ligadas na janela). null = degrau nao avaliado. Valor a confirmar pela Engenharia (BK-AUD-10): nao ha valor normativo adotado.", "janela_s": 10}, "bancos": {"56": {"id_medidor": "56", "db": 3000, "chaves_kw": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 4, 3]}, "400": {"id_medidor": "400", "db": 3100, "chaves_kw": [5, 5, 10, 10, 10, 10, 50, 50, 50, 50, 50, 50, 50]}, "595": {"id_medidor": "59,5", "db": 3200, "chaves_kw": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 3, 3, 2, 1, 0.5, 0.5, 0.5]}, "550": {"id_medidor": "550", "db": 3300, "chaves_kw": [5, 5, 5, 5, 5, 25, 50, 50, 100, 100, 100, 100]}}};
const cfg = global.get('bt2_capacidade') || PADRAO, g = cfg.gerador || {}, cli = global.get('bt2_kw100_cliente'), agora = Date.now();
const validade = Number(g.validade_s) || 180;
const idadeS = cli ? Math.round((agora - cli.ts) / 1000) : null;
const medidorValido = !!(cli && cli.kw100 > 0 && idadeS <= validade);
const efetivo = g.kw100 > 0 ? { kw100: Number(g.kw100), origem: 'arquivo' } : (medidorValido ? { kw100: Number(cli.kw100), origem: 'medidor' } : { kw100: null, origem: null });
const pct = Number(cfg.pctLim) || 110;
msg.statusCode = 200; msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { ok: true, modo: cfg.modo || 'registrar', pctLim: pct, kw100Arquivo: g.kw100 != null ? g.kw100 : null,
  kw100Medidor: cli ? { kw100: cli.kw100, modelo: cli.modelo, idadeS, valido: medidorValido } : null,
  efetivo, limiteKw: efetivo.kw100 ? Math.round(efetivo.kw100 * pct) / 100 : null, degrau: cfg.degrau || null };
return msg;
